# PPLGYM_SAMPLE  — forward: store type -> Beta prior; each barrel draws its own pRotten; |sum(B1(10))-sum(B2(10))|
function barrel_sum(a, b)
    p = Gen.random(beta, a, b)
    return sum(Gen.random(bernoulli, p) ? 1 : 0 for _ in 1:10)
end
store_prior() = Gen.random(bernoulli, 0.5) ? (0.1, 0.3) : (0.3, 0.1)
function same_store()
    sp = store_prior()                       # one store, shared prior; two distinct barrels
    return abs(barrel_sum(sp[1], sp[2]) - barrel_sum(sp[1], sp[2]))
end
function diff_store()
    sp1 = store_prior(); sp2 = store_prior()  # two stores, independent priors
    return abs(barrel_sum(sp1[1], sp1[2]) - barrel_sum(sp2[1], sp2[2]))
end
same = Int[]; diff = Int[]
for i in 1:10000
    push!(same, same_store()); push!(diff, diff_store())
end
ANSWER = Dict("sameStore" => same, "differentStore" => diff)
